insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-nutrimix-2-6','Little Joys Nutrimix | 350g | 2–6 Years (official product page)','https://ourlittlejoys.com/product/nutrimix-nutrition-powder','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["Age variant 2–6 years","Preparation: 2 scoops (30 g) in 200 ml lukewarm or cold milk = 1 serving","Not a meal replacement","Full Ingredients List (protein mix of skim milk powder & milk protein concentrate; jaggery & dates; cocoa; bajra, jowar, ragi, almond, walnut; vitamins & minerals; flavours; algal DHA; chicory root fibre; enzymes)"]'::jsonb,'The full ingredient list loads only after clicking ''View Full List of Ingredients''; it was captured from the live page by the project owner on 2026-10-18. Nutrition table is an image and was not transcribed.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-nutrimix-7-12','NutriMix Nutrition Powder 7+ (official product page)','https://ourlittlejoys.com/product/nutrimix-nutrition-powder-7','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["Age variant 7–12 years","Manufacturer states 9 g protein per serving"]'::jsonb,'Preparation instructions were not present in the retrieved page text (''How to use'' tab content not captured).');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-nutrimix-lactose-free','Nutrimix Lactose Free (350g) (official product page)','https://ourlittlejoys.com/product/nutrimix-lactose-intolerant','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["Preparation: ''Mix 2 scoops with water & drink up!''","''Our Lactose-Free Nutrimix contains other milk allergens.''","Labelled gluten free (manufacturer claim)"]'::jsonb,'No age range stated on the retrieved page.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-mvg-4-6','Multivitamin Gummies 4+ (30 Days Pack) (official product page)','https://ourlittlejoys.com/product/multivitamin-gummies','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["Selected variant label 4–6 Yr","30 gummies","Chicory root fibre base; no added sugar (manufacturer claim)"]'::jsonb,'Page metadata says ''2-9 Years'' while the visible variant label says ''4-6 Yr'' — conflict recorded. Daily usage instruction not captured.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-calcium-4-6','Calcium Gummies Strawberry (30N) (official product page)','https://ourlittlejoys.com/product/calcium-gummies-strawberry','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["''Every gummy delivers 100mg calcium and 300 IU Vitamin D3''","Vitamin D3 form: cholecalciferol (source lichen)"]'::jsonb,'Meta title says 4–12 Years; page title and variant label say 4–6 — conflict recorded. Daily usage instruction not captured.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-toothpaste-5','Multivitamin Toothpaste 5+ (80g) (official product page)','https://ourlittlejoys.com/product/multivitamin-toothpaste','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["For ages 5+","How to use: small amount on brush, brush gums and teeth in a circular motion"]'::jsonb,'Meta description says ''Fluoride free'' while a feature icon is labelled ''With Fluoride'' — conflict recorded.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-choco-fills','Little Joys Millet Choco Fills for Kids (official product page)','https://ourlittlejoys.com/product/millet-choco-fills','Little Joys by Mosaic Wellness Pvt Ltd','official_manufacturer_page','2026-10-18',null,'2026-10-18','approved','["Full ingredient list","Serving 25 g; 10 serves per 250 g (manufacturer Q&A)"]'::jsonb,'Variant label says ''2+ Yr'' but manufacturer Q&A says ''Kids 4+ years and adults'' — conflict recorded.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-blog-nutrimix-guide','What is Nutrimix? A complete guide for parents (Little Joys blog)','https://ourlittlejoys.com/blog/what-is-nutrimix-a-complete-guide-for-parents/','Little Joys (manufacturer blog)','manufacturer_blog','2026-10-18',null,'2026-10-18','approved','["''Can also be blended into smoothies or mixed into porridge.''","''designed to supplement a meal, not replace one''"]'::jsonb,'Blog says ''warm milk or water''; the product page says ''lukewarm or cold milk''. The product page is treated as the governing instruction.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-blog-protein-breakfast','How to Make a Protein-Rich Breakfast for Kids in 15 Minutes (Little Joys blog)','https://ourlittlejoys.com/blog/how-to-make-a-protein-rich-breakfast-for-kids-in-15-minutes/','Little Joys (manufacturer blog)','manufacturer_blog','2026-10-18','2026-04-14','2026-10-18','approved','["Recipe concepts: Nutrimix smoothie, peanut butter roti, curd with almonds and jaggery, scrambled eggs with roti, protein oats"]'::jsonb,'Smoothie uses ''one scoop'' with 200 ml milk, which differs from the product page''s 2 scoops (30 g) per 200 ml. Most recipes give no step-by-step method.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-lj-blog-ragi-pancake','Healthy Ragi Banana Pancake Recipe for Kids (Little Joys blog)','https://ourlittlejoys.com/blog/healthy-ragi-banana-pancake-recipe-for-kids/','Little Joys (manufacturer blog)','manufacturer_blog','2026-10-18','2025-11-06','2026-10-18','approved','["Ingredient quantities and method for ragi banana pancakes"]'::jsonb,'Ingredient list says 1 tsp pumpkin seed powder but the method says roast ''a handful''. No servings or times stated.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-icmr-dgi-2024','Dietary Guidelines for Indians (2024)','https://www.nin.res.in/dietaryguidelines/pdfjs/locale/DGI24thJune2024fin.pdf','ICMR – National Institute of Nutrition, Hyderabad','government_reference','2026-10-18','2024-05-08',null,'pending_review','["Eat a variety of foods","Moderate salt, sugar and ultra-processed foods","Discourages protein supplements for building body mass"]'::jsonb,'148-page document; only headline guidance used. Its RDA tables have NOT been imported into nutrient_references.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-aap-picky-eaters','10 Tips for Parents of Picky Eaters','https://www.healthychildren.org/English/ages-stages/toddler/nutrition/Pages/Picky-Eaters.aspx','American Academy of Pediatrics (HealthyChildren.org)','paediatric_guidance','2026-10-18',null,'2026-10-18','approved','["Picky eating is often a normal toddler stage","It can take 10 or more tastes before a toddler accepts a food","Pairing a bitter food with a familiar flavour can help","Family meals without screens"]'::jsonb,'');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-aap-preschool-feeding','How do I deal with my picky eater? (Preschool food and feeding)','https://www.healthychildren.org/english/healthy-living/growing-healthy/pages/preschool-food-and-feeding.aspx','American Academy of Pediatrics (HealthyChildren.org)','paediatric_guidance','2026-10-18',null,'2026-10-18','approved','["Offer new foods with familiar foods","Let the child choose between two healthy options","Don''t force eating; don''t use favourite foods as rewards"]'::jsonb,'');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-who-cf-2023','WHO Guideline for complementary feeding of infants and young children 6–23 months of age','https://www.who.int/timorleste/publications/i/item/9789240081864','World Health Organization','public_health_guidance','2026-10-18','2023-10-16','2026-10-18','approved','["Diverse diet for 6–23 months","Responsive feeding","Fortified products may help only where needs cannot be met with unfortified foods"]'::jsonb,'Used only to frame under-2 guidance; no recipes or products are generated for this age group.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-ods-calcium','Calcium — Fact Sheet for Consumers','https://ods.od.nih.gov/factsheets/Calcium-Consumer/','NIH Office of Dietary Supplements (USA)','government_reference','2026-10-18','2023-09-14','2026-10-18','approved','["Milk, yogurt and cheese are main food sources","Some vegetables (e.g. kale, broccoli) contain calcium","Some foods are fortified — check labels","Tell health care providers about supplements"]'::jsonb,'US-focused reference; used for general food-source education only.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-ods-iron','Iron — Fact Sheet for Consumers','https://ods.od.nih.gov/factsheets/Iron-Consumer/','NIH Office of Dietary Supplements (USA)','government_reference','2026-10-18','2023-08-17','2026-10-18','approved','["Plant foods and fortified foods provide nonheme iron; legumes, spinach, nuts, dried fruit are sources","Vitamin C-containing foods improve absorption of nonheme iron","Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6"]'::jsonb,'US-focused reference; used for general food-source and safety education only.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-ods-vitamin-d','Vitamin D — Fact Sheet for Consumers','https://ods.od.nih.gov/factsheets/VitaminD-Consumer/','NIH Office of Dietary Supplements (USA)','government_reference','2026-10-18','2022-11-08','2026-10-18','approved','["Very few foods naturally contain vitamin D","The body makes vitamin D when bare skin is exposed to the sun","Too much vitamin D can be harmful, almost always from supplements"]'::jsonb,'US-focused reference.');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-kidshealth-allergy-labels','Food Allergies: How to Read a Food Label','https://kidshealth.org/RadyChildrens/en/parents/foodallergy-labels.html','Nemours KidsHealth (reviewed by Larissa Hirsch, MD, Jan 2023)','paediatric_guidance','2026-10-18','2023-01-01','2026-10-18','approved','["Read labels every time","Advisory ''may contain'' warnings are voluntary","Cross-contact and ingredient changes","Contact the manufacturer when unsure"]'::jsonb,'');
insert into evidence_sources (id,title,url,publisher,source_type,retrieved_at,published_at,reviewed_at,review_status,claims_supported,notes) values ('src-hmh-constipation','A Pediatrician''s Advice About Constipation','https://hackensackmeridianhealth.org/en/healthu/2023/05/31/a-pediatricians-advice-about-constipation','Hackensack Meridian Health (Shamila B Zawahir, MD)','hospital_patient_education','2026-10-18','2023-05-31','2026-10-18','approved','["See a doctor if constipation lasts more than two weeks, or sooner with fever, vomiting, weight loss, blood in stool, rectal bleeding or bloating","Fluids and fibre-rich foods"]'::jsonb,'Updated 2025-10-01 per page.');
insert into products (id,brand,product_family,variant_name,category,flavour,pack_size,age_min_months,age_max_months,age_guidance_text,ingredients,nutrient_data,allergen_data,official_instructions,warnings,description,official_url,image_url,source_type,last_fetched_at,last_reviewed_at,reviewed_by,review_status,recommendation_eligible,active,field_status,conflicts,notes,source_ids,created_at,updated_at) values ('lj-nutrimix-2-6-chocolate-350g','Little Joys','Nutrimix Nutrition Powder','Nutrimix 2–6 Years · Chocolate · With Jaggery & Dates · 350 g jar','nutrition_powder','Chocolate','350 g jar',24,83,'2–6 Yr (variant selector). Manufacturer FAQ: ''suitable for every child of age 2 years & above''.','{"items":[{"name":"Skim milk powder","allergens":["milk"],"share":"Protein mix"},{"name":"Milk protein concentrate","allergens":["milk"],"share":"Protein mix"},{"name":"Jaggery powder","allergens":[],"share":"Nutri sweet mix"},{"name":"Dates powder","allergens":[],"share":"Nutri sweet mix"},{"name":"Cocoa solids","allergens":[]},{"name":"Bajra powder","allergens":[],"share":"Millets & nuts mix"},{"name":"Jowar powder","allergens":[],"share":"Millets & nuts mix"},{"name":"Ragi powder","allergens":[],"share":"Millets & nuts mix"},{"name":"Almond powder","allergens":["tree_nut"],"share":"Millets & nuts mix"},{"name":"Walnut powder","allergens":["tree_nut"],"share":"Millets & nuts mix"},{"name":"Vitamins & minerals","allergens":[]},{"name":"Nature identical flavours (chocolate & vanilla)","allergens":[]},{"name":"Algal DHA (docosahexaenoic acid)","allergens":[]},{"name":"Chicory root fibre (inulin)","allergens":[]},{"name":"Enzymes blend (amylase & cellulase)","allergens":[]}],"completeness":"complete","note":"Full Ingredients List as shown on the official page after clicking ''View Full List of Ingredients'' (captured by the project owner, 2026-10-18). Individual vitamins/minerals are not itemised. No formal allergen or cross-contact statement was found."}'::jsonb,'{"items":[{"nutrient":"Protein","amount":"5","unit":"g","per":"serving (as stated by manufacturer)"},{"nutrient":"Vitamins & minerals","amount":"23","unit":"nutrients","per":"product (manufacturer claim)"},{"nutrient":"Calcium","amount":"70% RDA (1–3 yrs) / 63.83% RDA (4–6 yrs)","unit":"","per":"basis not specified","note":"Manufacturer claim; RDA reference not named on page."},{"nutrient":"Vitamin D3","amount":"50% RDA","unit":"","per":"basis not specified","note":"Manufacturer claim; ''veg source''."}],"completeness":"partial","manufacturer_stated":true,"note":"The nutrition information table is published as an image and has not been transcribed or verified."}'::jsonb,'{"contains":["milk","tree_nut"],"preparation_adds":["milk"],"statement":null,"basis":"derived_from_ingredient_list","cross_contact_info":null}'::jsonb,'{"text":"Mix 2 scoops (30 g) of the nutrition powder with 200 ml of lukewarm or cold milk to prepare 1 serving.","verified":true,"source_quote":"Mix 2 scoops (30 g) of the nutrition powder with 200 ml of lukewarm or cold milk to prepare 1 serving of Nutrimix.","note":"Daily frequency is not stated on the product page."}'::jsonb,'["Manufacturer FAQ: use Nutrimix as a supplement to a well-balanced diet. It is not a replacement for a meal."]'::jsonb,'Chocolate-flavoured nutrition powder for 2–6 year olds, made with millets and dry fruits and sweetened with jaggery and dates (manufacturer description).','https://ourlittlejoys.com/product/nutrimix-nutrition-powder',null,'official_manufacturer_page','2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z','Build-time check against official page (AI-assisted, 2026-10-18). Not a professional or manufacturer review.','approved',true,true,'{"age_guidance":"verified","ingredients":"verified","allergens":"unverified","instructions":"verified","warnings":"unverified"}'::jsonb,'["The page description mentions oats, but the Full Ingredients List does not include oats.","Little Joys blog smoothie uses ''one scoop'' per 200 ml milk; the product page says 2 scoops (30 g) per 200 ml. The product page is treated as the governing instruction.","Little Joys blog says ''warm milk or water''; the product page says ''lukewarm or cold milk''."]'::jsonb,'["Official product image not used: image licensing not confirmed.","The powder itself contains milk (skim milk powder, milk protein concentrate) — not only the milk used to prepare it.","Allergens are derived from the ingredient list; no formal allergen statement found."]'::jsonb,array['src-lj-nutrimix-2-6','src-lj-blog-nutrimix-guide']::text[],'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
