insert into products (id,brand,product_family,variant_name,category,flavour,pack_size,age_min_months,age_max_months,age_guidance_text,ingredients,nutrient_data,allergen_data,official_instructions,warnings,description,official_url,image_url,source_type,last_fetched_at,last_reviewed_at,reviewed_by,review_status,recommendation_eligible,active,field_status,conflicts,notes,source_ids,created_at,updated_at) values ('lj-multivitamin-toothpaste-5plus-80g','Little Joys','Toothpaste','Multivitamin Toothpaste 5+ · Strawberry · 80 g','oral_care','Strawberry','80 g',60,null,'''For Ages 5+''','{"items":[{"name":"Aloe vera","allergens":[]},{"name":"Neem oil","allergens":[]},{"name":"Triphala","allergens":[]},{"name":"Pomegranate","allergens":[]},{"name":"Vitamin B, Vitamin D3, Vitamin E","allergens":[]}],"completeness":"partial","note":"Highlighted ingredients only."}'::jsonb,'{"items":[],"completeness":"unknown","manufacturer_stated":true,"note":"Not applicable (oral-care product)."}'::jsonb,'{"contains":[],"preparation_adds":[],"statement":null,"basis":"unknown","cross_contact_info":null}'::jsonb,'{"text":"Take a small amount of toothpaste on the brush and gently brush gums and teeth in a circular motion.","verified":true,"source_quote":"Take a small amount of toothpaste on the brush and gently brush gums and teeth in a circular motion on teeth to clean properly.","note":""}'::jsonb,'[]'::jsonb,'Strawberry-flavoured children''s toothpaste for ages 5+ (manufacturer description).','https://ourlittlejoys.com/product/multivitamin-toothpaste',null,'official_manufacturer_page','2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z','Build-time check against official page (AI-assisted, 2026-10-18). Not a professional or manufacturer review.','approved',false,true,'{"age_guidance":"verified","ingredients":"unverified","allergens":"missing","instructions":"verified","warnings":"missing"}'::jsonb,'["Fluoride: page metadata says ''Fluoride free'' while a feature icon is labelled ''With Fluoride''. Check the pack or ask the manufacturer."]'::jsonb,'["Oral-care product: handled separately from the nutrition engine."]'::jsonb,array['src-lj-toothpaste-5']::text[],'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
