insert into products (id,brand,product_family,variant_name,category,flavour,pack_size,age_min_months,age_max_months,age_guidance_text,ingredients,nutrient_data,allergen_data,official_instructions,warnings,description,official_url,image_url,source_type,last_fetched_at,last_reviewed_at,reviewed_by,review_status,recommendation_eligible,active,field_status,conflicts,notes,source_ids,created_at,updated_at) values ('lj-millet-choco-fills-250g','Little Joys','Millet Choco Fills','Millet Choco Fills · 250 g','snack','Chocolate','250 g',48,null,'Variant label ''2+ Yr''; manufacturer Q&A ''Kids 4+ years and adults''.','{"items":[{"name":"Ragi powder","allergens":[],"share":"Millet blend 37.2%"},{"name":"Red rice powder","allergens":[],"share":"Millet blend 37.2%"},{"name":"Foxtail powder","allergens":[],"share":"Millet blend 37.2%"},{"name":"Jowar powder","allergens":[],"share":"Millet blend 37.2%"},{"name":"Groundnut oil","allergens":["peanut"],"share":"Binder 23.9%"},{"name":"Rice bran oil","allergens":[],"share":"Binder 23.9%"},{"name":"Sunflower lecithin","allergens":[],"share":"Binder 23.9%"},{"name":"Jaggery powder","allergens":[],"share":"Nutri sweet 19.5%"},{"name":"Dates powder","allergens":[],"share":"Nutri sweet 19.5%"},{"name":"Cocoa powder","allergens":[],"share":"Taste maker 19.4%"},{"name":"Skim milk powder","allergens":["milk"],"share":"Taste maker 19.4%"},{"name":"Salt","allergens":[],"share":"Taste maker 19.4%"},{"name":"Chocolate flavour (natural & nature-identical)","allergens":[],"share":"Taste maker 19.4%"}],"completeness":"complete","note":"Full ''List of Ingredients'' as printed on the official page."}'::jsonb,'{"items":[],"completeness":"unknown","manufacturer_stated":true,"note":"Nutrition table not captured."}'::jsonb,'{"contains":["peanut","milk"],"preparation_adds":[],"statement":null,"basis":"derived_from_ingredient_list","cross_contact_info":null}'::jsonb,'{"text":"Ready-to-eat cereal/snack. Serving size 25 g (10 serves per 250 g pack).","verified":true,"source_quote":"25 g per serve; 10 serves per 250 g pack.","note":"Taken from the manufacturer''s Q&A section."}'::jsonb,'[]'::jsonb,'Crunchy millet cereal shells with a jaggery-sweetened cocoa filling (manufacturer description).','https://ourlittlejoys.com/product/millet-choco-fills',null,'official_manufacturer_page','2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z','Build-time check against official page (AI-assisted, 2026-10-18). Not a professional or manufacturer review.','approved',false,true,'{"age_guidance":"conflict","ingredients":"verified","allergens":"unverified","instructions":"verified","warnings":"missing"}'::jsonb,'["Age guidance: ''2+ Yr'' (variant label) vs ''Kids 4+ years and adults'' (Q&A). The stricter 4+ is stored."]'::jsonb,'["Allergens are derived from the ingredient list; no formal allergen or cross-contact statement was found. Groundnut oil = peanut source."]'::jsonb,array['src-lj-choco-fills']::text[],'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
