insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('nutrimix-banana-smoothie','Nutrimix banana smoothie','One pack-prepared serving of Nutrimix blended with half a banana for a thicker, fruitier drink.',24,83,array['drink','breakfast','snack']::text[],'[{"name":"Little Joys Nutrimix 2–6 (Chocolate)","quantity":"1 serving, prepared exactly as the pack says","unit":"","allergens":["tree_nut","milk"],"diet_flags":[],"optional":false,"product_id":"lj-nutrimix-2-6-chocolate-350g"},{"name":"Cold milk (as used in the pack instruction)","quantity":"200","unit":"ml","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Ripe banana","quantity":"½","unit":"","allergens":[],"diet_flags":[],"optional":false}]'::jsonb,'["Prepare one serving of Nutrimix exactly as the pack instructs, using cold milk.","Add half a ripe banana.","Blend for about 30 seconds until smooth and serve straight away."]'::jsonb,3,0,'easy',array['tree_nut','milk']::text[],array['vegetarian','egg_free']::text[],array['dairy','fruit']::text[],array['smooth','drinkable']::text[],array['product_question','picky_eating','meal_prep']::concern_type[],null,'Changes the taste and thickness of a drink your child already knows, which some parents find helps when a child gets bored of the usual glass.','[{"for":"Banana","use":"3–4 ripe strawberries","note":"Only if your child already accepts strawberries."}]'::jsonb,'["Use one serving prepared as per the pack — do not add extra powder.","The Little Joys blog version uses one scoop per 200 ml; this app follows the product page (2 scoops / 30 g per 200 ml) until the difference is resolved."]'::jsonb,'adapted_from_source',array['src-lj-blog-protein-breakfast','src-lj-nutrimix-2-6']::text[],'Concept from the Little Joys blog (''NutriMix smoothie''); quantity aligned to the product page instruction.','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('nutrimix-oats-stir-in','Oats porridge with Nutrimix stirred in once lukewarm','Soft oats cooked in milk, cooled to lukewarm, with one serving of Nutrimix stirred in for flavour.',24,83,array['breakfast']::text[],'[{"name":"Rolled oats","quantity":"3","unit":"tbsp","allergens":["gluten"],"diet_flags":[],"optional":false},{"name":"Milk","quantity":"200","unit":"ml","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Little Joys Nutrimix 2–6 (Chocolate)","quantity":"2 scoops (30 g) — one pack serving","unit":"","allergens":["tree_nut","milk"],"diet_flags":[],"optional":false,"product_id":"lj-nutrimix-2-6-chocolate-350g"},{"name":"Finely ground almonds or walnuts","quantity":"1","unit":"tsp","allergens":["tree_nut"],"diet_flags":[],"optional":true}]'::jsonb,'["Simmer the oats in the milk, stirring, until soft (about 5 minutes).","Take off the heat and let it cool until just lukewarm.","Stir in one serving of Nutrimix until smooth. Do not reheat after adding it.","Top with a little finely ground nut if your child eats nuts."]'::jsonb,2,5,'easy',array['gluten','milk','tree_nut']::text[],array['vegetarian','egg_free']::text[],array['whole grains','dairy']::text[],array['soft','creamy']::text[],array['product_question','picky_eating']::concern_type[],null,'Turns a familiar flavour into a warm, spoonable breakfast — a different texture from the usual drink.','[{"for":"Rolled oats","use":"Ragi flour porridge (2 tbsp cooked in the milk)","note":"Avoids oats if gluten cross-contact is a concern."}]'::jsonb,'["Heating Nutrimix is not covered by the pack instruction (''lukewarm or cold milk''), so it is added only after cooling.","Oats are tagged as a possible gluten source because of common cross-contact.","For young children, serve nuts finely ground or as a smooth paste — whole or chopped nuts are a choking risk."]'::jsonb,'adapted_from_source',array['src-lj-blog-protein-breakfast','src-lj-blog-nutrimix-guide','src-lj-nutrimix-2-6']::text[],'Little Joys blog suggests stirring a scoop of NutriMix into protein oats, and says it ''can be … mixed into porridge''. Whether it is added before or after cooking is not stated.','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('curd-almond-jaggery-bowl','Curd bowl with ground almonds and jaggery','Plain curd topped with finely ground almonds and a little jaggery — no cooking.',24,null,array['breakfast','snack']::text[],'[{"name":"Plain curd (dahi)","quantity":"100","unit":"g","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Almonds, finely ground","quantity":"8–10","unit":"almonds","allergens":["tree_nut"],"diet_flags":[],"optional":false},{"name":"Jaggery powder","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false}]'::jsonb,'["Spoon the curd into a bowl.","Sprinkle over the ground almonds and jaggery.","Stir lightly and serve."]'::jsonb,2,0,'easy',array['milk','tree_nut']::text[],array['vegetarian','egg_free']::text[],array['dairy','nuts & seeds']::text[],array['creamy']::text[],array['calcium','protein_foods','meal_prep','appetite']::concern_type[],null,'Ready in two minutes with no cooking; includes curd, a dairy food (dairy foods are listed by NIH ODS as main food sources of calcium).','[{"for":"Almonds","use":"Roasted, ground pumpkin or sunflower seeds","note":"For tree-nut avoidance — check seeds are tolerated."},{"for":"Jaggery","use":"Mashed ripe banana","note":"Sweetness from fruit instead."}]'::jsonb,'["For young children, serve nuts finely ground or as a smooth paste — whole or chopped nuts are a choking risk."]'::jsonb,'documented_source',array['src-lj-blog-protein-breakfast','src-ods-calcium']::text[],'Quantities from the Little Joys blog (''100g plain curd, 8-10 crushed almonds, a teaspoon of jaggery'').','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('ragi-banana-pancakes','Ragi banana pancakes','Soft pancakes made with sprouted ragi, wheat and almond flours, sweetened with banana and dates.',24,null,array['breakfast','snack']::text[],'[{"name":"Sprouted ragi flour","quantity":"2","unit":"cups","allergens":[],"diet_flags":[],"optional":false},{"name":"Whole wheat flour","quantity":"1","unit":"cup","allergens":["wheat","gluten"],"diet_flags":[],"optional":false},{"name":"Almond flour","quantity":"4","unit":"tsp","allergens":["tree_nut"],"diet_flags":[],"optional":false},{"name":"Green cardamom pods (ground)","quantity":"2","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Pumpkin seed powder","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Ripe bananas, mashed","quantity":"2","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Dates, soaked 2–3 hours","quantity":"2","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Cinnamon","quantity":"a pinch","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Baking soda","quantity":"a pinch","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Milk, added gradually","quantity":"2","unit":"cups","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Ghee, for the pan","quantity":"as needed","unit":"","allergens":["milk"],"diet_flags":["dairy"],"optional":false}]'::jsonb,'["Combine the ragi, wheat and almond flours in a bowl.","Grind roasted pumpkin seeds with the cardamom and mix into the flour.","Mix in the mashed bananas, cinnamon and baking soda.","Blend the soaked dates with some of the milk into a smooth paste and add to the batter.","Add more milk gradually until the batter is smooth and pourable; rest 10–15 minutes.","Brush a pan with ghee, pour a ladle of batter and cook on low heat until golden on both sides."]'::jsonb,20,15,'moderate',array['wheat','gluten','tree_nut','milk']::text[],array['vegetarian','egg_free']::text[],array['whole grains','fruit','dairy','nuts & seeds']::text[],array['soft']::text[],array['picky_eating','fruit_veg']::concern_type[],null,'A familiar pancake shape with fruit sweetness — makes a batch, so leftovers can cover another breakfast.','[{"for":"Ghee","use":"A neutral cooking oil","note":"Removes the dairy from cooking fat; the batter still contains milk."},{"for":"Milk","use":"Water or a fortified plant milk","note":"Check the plant milk''s own allergen label."}]'::jsonb,'["This is a large batch; the source gives no serving count.","The source lists 1 tsp pumpkin seed powder but its method says to roast ''a handful'' — 1 tsp is used here.","Times are NutriGuide estimates; the source does not state them.","The source tops the pancakes with a chocolate hazelnut spread — left out here."]'::jsonb,'documented_source',array['src-lj-blog-ragi-pancake']::text[],'Little Joys blog, 06 Nov 2025 (recipe shared by Dr. Arpana Kaur Narang).','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('egg-bhurji-roti','Soft scrambled egg with roti','One or two eggs gently scrambled with mild seasoning, served with roti or toast.',24,null,array['breakfast','dinner']::text[],'[{"name":"Eggs","quantity":"1–2","unit":"","allergens":["egg"],"diet_flags":["egg"],"optional":false},{"name":"Ghee","quantity":"1","unit":"tsp","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Mild seasoning (pinch of salt, turmeric)","quantity":"a pinch","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Whole wheat roti or toast","quantity":"1","unit":"","allergens":["wheat","gluten"],"diet_flags":[],"optional":false}]'::jsonb,'["Beat the eggs with a pinch of salt and turmeric.","Warm the ghee in a pan on low heat, add the eggs and stir gently until fully cooked and soft.","Serve with roti or toast, torn into pieces your child can hold."]'::jsonb,2,5,'easy',array['egg','milk','wheat','gluten']::text[],array['vegetarian_eggs','non_vegetarian']::text[],array['eggs','whole grains']::text[],array['soft']::text[],array['protein_foods','meal_prep']::concern_type[],null,'A quick cooked breakfast; eggs are a protein-containing food.','[{"for":"Ghee","use":"A neutral cooking oil","note":"Removes the milk-derived ingredient."}]'::jsonb,'["Cook eggs until no runny parts remain."]'::jsonb,'documented_source',array['src-lj-blog-protein-breakfast']::text[],'Little Joys blog (''One or two eggs scrambled in ghee with mild seasoning, served with a roti or toast'').','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('peanut-butter-roti-pinwheels','Peanut butter roti pinwheels','Leftover roti spread thinly with natural peanut butter, rolled and sliced into pinwheels.',24,null,array['breakfast','snack']::text[],'[{"name":"Leftover whole wheat roti","quantity":"1","unit":"","allergens":["wheat","gluten"],"diet_flags":[],"optional":false},{"name":"Natural peanut butter","quantity":"a thin layer","unit":"","allergens":["peanut"],"diet_flags":[],"optional":false},{"name":"Thin banana slices","quantity":"a few","unit":"","allergens":[],"diet_flags":[],"optional":true}]'::jsonb,'["Warm the roti briefly so it rolls without cracking.","Spread a thin, even layer of peanut butter (thick dollops can be hard for young children to swallow).","Add banana slices if using, roll tightly and slice into rounds."]'::jsonb,3,0,'easy',array['wheat','gluten','peanut']::text[],array['vegetarian','egg_free','dairy_free']::text[],array['whole grains','legumes','fruit']::text[],array['soft','chewy']::text[],array['picky_eating','protein_foods','meal_prep']::concern_type[],null,'Same roti, new shape — pinwheels are easy to hold and can make a familiar food feel new.','[{"for":"Peanut butter","use":"Thick curd with a little jaggery","note":"For peanut avoidance (contains milk)."}]'::jsonb,'["Spread peanut butter thinly for young children."]'::jsonb,'adapted_from_source',array['src-lj-blog-protein-breakfast']::text[],'Little Joys blog lists ''Leftover roti spread with natural peanut butter''; the pinwheel presentation is a NutriGuide addition.','review_required',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('besan-veg-cheela','Mini besan cheela with grated vegetables','Small, soft gram-flour pancakes with finely grated carrot and spinach cooked into the batter.',24,null,array['breakfast','dinner','snack']::text[],'[{"name":"Besan (gram flour)","quantity":"½","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Water","quantity":"about ⅓","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Carrot, finely grated","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Spinach, very finely chopped","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Salt and turmeric","quantity":"a pinch each","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Cooking oil","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false}]'::jsonb,'["Whisk the besan and water into a smooth, pourable batter.","Stir in the carrot, spinach, salt and turmeric.","Cook small rounds on a lightly oiled pan over medium-low heat, about 2 minutes a side, until set through.","Serve warm, cut into strips if your child prefers."]'::jsonb,7,8,'easy',array[]::text[],array['vegetarian','egg_free','dairy_free','vegan_possible']::text[],array['legumes','vegetables']::text[],array['soft']::text[],array['fruit_veg','picky_eating','iron','protein_foods']::concern_type[],null,'Vegetables are cooked into a familiar pancake form. Includes a legume flour and spinach — plant foods NIH ODS lists among iron sources.','[{"for":"Spinach","use":"Grated bottle gourd or finely chopped methi","note":"Rotate vegetables to build familiarity."},{"for":"Water","use":"Thin curd (for a softer cheela)","note":"Adds milk."}]'::jsonb,'["Chickpea (besan) is a legume; some children with legume allergies react to it."]'::jsonb,'original_demo_concept',array['src-aap-picky-eaters','src-ods-iron']::text[],'Original NutriGuide concept. Quantities not professionally reviewed.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('moong-dal-veg-khichdi','Soft moong dal khichdi with mashed vegetables','One-pot rice and yellow moong dal cooked soft with mashed vegetables, finished with a squeeze of lemon.',24,null,array['lunch','dinner']::text[],'[{"name":"Rice","quantity":"¼","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Yellow moong dal","quantity":"¼","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Mixed vegetables (carrot, bottle gourd, peas), chopped","quantity":"½","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Water","quantity":"2","unit":"cups","allergens":[],"diet_flags":[],"optional":false},{"name":"Cumin seeds, turmeric, salt","quantity":"a pinch each","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Cooking oil","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Ghee, to finish","quantity":"½","unit":"tsp","allergens":["milk"],"diet_flags":["dairy"],"optional":true},{"name":"Lemon juice","quantity":"a few drops","unit":"","allergens":[],"diet_flags":[],"optional":false}]'::jsonb,'["Rinse the rice and dal together.","Warm the oil, add cumin, then the vegetables, rice, dal, turmeric, salt and water.","Pressure-cook for 3–4 whistles (or simmer covered ~25 minutes) until very soft.","Mash to the texture your child accepts; finish with a few drops of lemon (and ghee if using)."]'::jsonb,10,20,'easy',array[]::text[],array['vegetarian','egg_free','dairy_free','vegan_possible']::text[],array['legumes','whole grains','vegetables']::text[],array['soft','mashed']::text[],array['iron','fruit_veg','meal_prep','feeding_symptom','appetite']::concern_type[],null,'One pot, adjustable texture. Includes lentils (a plant iron source per NIH ODS) and lemon, a vitamin C food that ODS says helps the body absorb plant iron.','[{"for":"Bottle gourd","use":"Pumpkin or spinach","note":"Mash well for children who dislike visible vegetables."}]'::jsonb,'["Let it cool to a safe eating temperature before serving."]'::jsonb,'original_demo_concept',array['src-ods-iron','src-hmh-constipation']::text[],'Original NutriGuide concept.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('ragi-porridge-dairy-free','Ragi porridge (dairy-free base)','Smooth finger-millet porridge cooked in water with jaggery and cardamom; milk is optional.',24,null,array['breakfast','snack']::text[],'[{"name":"Ragi flour","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Water","quantity":"1","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Jaggery powder","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Cardamom powder","quantity":"a pinch","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Milk, to finish","quantity":"2–3","unit":"tbsp","allergens":["milk"],"diet_flags":["dairy"],"optional":true}]'::jsonb,'["Whisk the ragi flour into cold water until there are no lumps.","Cook on low heat, stirring constantly, for 6–8 minutes until thick and glossy.","Stir in jaggery and cardamom; thin with a little milk if your child likes it creamier."]'::jsonb,2,8,'easy',array[]::text[],array['vegetarian','egg_free','dairy_free','vegan_possible']::text[],array['whole grains']::text[],array['smooth','soft']::text[],array['picky_eating','feeding_symptom','meal_prep']::concern_type[],null,'A smooth, familiar-tasting porridge that works without milk — useful when dairy is being avoided.','[{"for":"Milk (optional)","use":"A fortified plant milk","note":"Check its allergen label."}]'::jsonb,'["Stir constantly — ragi thickens quickly and can stick."]'::jsonb,'original_demo_concept',array[]::text[],'Original NutriGuide concept.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('paneer-bhurji-roti-wrap','Paneer bhurji roti wrap','Crumbled paneer cooked with tomato and peas, rolled in a soft roti.',24,null,array['lunch','dinner']::text[],'[{"name":"Paneer, crumbled","quantity":"50","unit":"g","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Tomato, finely chopped","quantity":"1","unit":"small","allergens":[],"diet_flags":[],"optional":false},{"name":"Green peas","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Onion, finely chopped","quantity":"1","unit":"tbsp","allergens":[],"diet_flags":[],"optional":true},{"name":"Cooking oil","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Salt, turmeric","quantity":"a pinch each","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Whole wheat roti","quantity":"1","unit":"","allergens":["wheat","gluten"],"diet_flags":[],"optional":false}]'::jsonb,'["Cook the onion (if using) in oil until soft, then add tomato and peas and cook until soft.","Add the paneer, salt and turmeric; stir 2 minutes.","Spoon onto a warm roti, roll and cut in half."]'::jsonb,5,8,'easy',array['milk','wheat','gluten']::text[],array['vegetarian','egg_free']::text[],array['dairy','vegetables','whole grains']::text[],array['soft','crumbly']::text[],array['calcium','protein_foods','fruit_veg']::concern_type[],null,'Includes paneer, a dairy food (NIH ODS lists cheese among main calcium food sources), with vegetables tucked into a familiar wrap.','[{"for":"Paneer","use":"Firm tofu, crumbled","note":"Dairy-free option; tofu contains soy."}]'::jsonb,'[]'::jsonb,'original_demo_concept',array['src-ods-calcium']::text[],'Original NutriGuide concept.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('rainbow-fruit-plate-curd-dip','Rainbow fruit plate with curd dip','Three or four colours of fruit cut into easy pieces, with a small bowl of curd for dipping.',24,null,array['snack','breakfast']::text[],'[{"name":"Banana slices","quantity":"½","unit":"banana","allergens":[],"diet_flags":[],"optional":false},{"name":"Papaya cubes","quantity":"3–4","unit":"pieces","allergens":[],"diet_flags":[],"optional":false},{"name":"Apple, thin slices","quantity":"4","unit":"slices","allergens":[],"diet_flags":[],"optional":false},{"name":"Pomegranate seeds","quantity":"1","unit":"tbsp","allergens":[],"diet_flags":[],"optional":true},{"name":"Plain curd, for dipping","quantity":"2","unit":"tbsp","allergens":["milk"],"diet_flags":["dairy"],"optional":false},{"name":"Cinnamon","quantity":"a pinch","unit":"","allergens":[],"diet_flags":[],"optional":true}]'::jsonb,'["Cut the fruit into thin slices or small cubes your child can pick up.","Arrange by colour on a plate, including one fruit your child already likes.","Serve with curd (and a pinch of cinnamon) for dipping."]'::jsonb,5,0,'easy',array['milk']::text[],array['vegetarian','egg_free']::text[],array['fruit','dairy']::text[],array['crunchy','soft']::text[],array['fruit_veg','picky_eating','appetite','calcium']::concern_type[],null,'Puts a new fruit next to a familiar one and lets your child choose — an approach AAP suggests for picky eaters.','[{"for":"Curd dip","use":"Thin peanut butter (if no peanut allergy)","note":"Dairy-free dip."}]'::jsonb,'["Cut round fruit such as grapes lengthwise into quarters for young children.","Slice apple thinly for younger children."]'::jsonb,'original_demo_concept',array['src-aap-preschool-feeding','src-aap-picky-eaters']::text[],'Original NutriGuide concept based on AAP picky-eating strategies.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipes (id,name,description,age_min_months,age_max_months,meal_types,ingredients,preparation_steps,prep_time_minutes,cook_time_minutes,difficulty,allergens,dietary_tags,food_groups,textures,concern_tags,nutritional_information,benefit_description,substitutions,caveats,source_status,source_ids,source_notes,review_status,active,created_at,updated_at) values ('vegetable-poha','Vegetable poha with peas','Soft flattened rice with peas and grated carrot, lightly tempered.',24,null,array['breakfast','snack']::text[],'[{"name":"Thick poha (flattened rice)","quantity":"½","unit":"cup","allergens":[],"diet_flags":[],"optional":false},{"name":"Green peas","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Carrot, grated","quantity":"2","unit":"tbsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Mustard seeds","quantity":"¼","unit":"tsp","allergens":["mustard"],"diet_flags":[],"optional":false},{"name":"Curry leaves, turmeric, salt","quantity":"a few / a pinch","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Cooking oil","quantity":"1","unit":"tsp","allergens":[],"diet_flags":[],"optional":false},{"name":"Lemon juice","quantity":"a few drops","unit":"","allergens":[],"diet_flags":[],"optional":false},{"name":"Roasted peanuts, ground","quantity":"1","unit":"tsp","allergens":["peanut"],"diet_flags":[],"optional":true}]'::jsonb,'["Rinse the poha in a sieve and let it soften for 5 minutes.","Temper mustard seeds and curry leaves in oil; add peas and carrot and cook until soft.","Add poha, turmeric and salt; toss on low heat for 2–3 minutes.","Finish with lemon (and ground peanuts if using). Remove curry leaves for young children."]'::jsonb,7,8,'easy',array['mustard']::text[],array['vegetarian','egg_free','dairy_free','vegan_possible']::text[],array['whole grains','vegetables','legumes']::text[],array['soft','fluffy']::text[],array['fruit_veg','picky_eating','meal_prep']::concern_type[],null,'A quick savoury breakfast where small, soft vegetables mix in rather than sit on the side.','[{"for":"Mustard seeds","use":"Cumin seeds","note":"For mustard avoidance."}]'::jsonb,'["Peanuts are optional and listed separately — leave out for peanut allergy."]'::jsonb,'original_demo_concept',array[]::text[],'Original NutriGuide concept.','demo',true,'2026-10-18T07:30:00.000Z','2026-10-18T07:30:00.000Z');
insert into recipe_products (id,recipe_id,product_id,use_description,validated_quantity,quantity_unit,usage_constraints,evidence_source_id,review_status,conflict_notes) values ('rp-smoothie-nutrimix-2-6','nutrimix-banana-smoothie','lj-nutrimix-2-6-chocolate-350g','One serving prepared exactly as per the pack (2 scoops / 30 g in 200 ml cold milk), then blended with half a banana.',null,null,'["Use one pack serving only — do not increase.","Cold or lukewarm milk only, as the pack instructs."]'::jsonb,'src-lj-blog-protein-breakfast','pending_review','Manufacturer blog uses one scoop per 200 ml; product page says 2 scoops (30 g) per 200 ml.');
insert into recipe_products (id,recipe_id,product_id,use_description,validated_quantity,quantity_unit,usage_constraints,evidence_source_id,review_status,conflict_notes) values ('rp-oats-nutrimix-2-6','nutrimix-oats-stir-in','lj-nutrimix-2-6-chocolate-350g','One serving (2 scoops / 30 g) stirred into 200 ml of milk-cooked oats after cooling to lukewarm.',null,null,'["Add only after cooling to lukewarm — heating is not covered by the pack instruction.","Do not reheat after adding."]'::jsonb,'src-lj-blog-nutrimix-guide','pending_review','Blog does not say whether Nutrimix is added before or after cooking.');
