insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-picky-eating','picky_eating','Picky eating is common — and usually a phase','["Picky eating is often a normal developmental stage, especially in toddlers and young children, as growth and appetite slow after infancy.","Children may need to taste a new food many times — AAP mentions 10 or more tries — before accepting it."]'::jsonb,'["Offer a new food alongside one your child already likes.","Let your child choose between two healthy options.","Pair a less-liked flavour with a familiar one (AAP gives the example of broccoli with grated cheese).","Eat together without screens where possible, and avoid pressure, bribes or using favourite foods as rewards."]'::jsonb,'["Which foods does your child reliably accept?","Are there textures your child prefers (smooth, crunchy, soft)?"]'::jsonb,'["Pick one familiar food and try one small change to how it''s served.","Offer one new food at a time, in a tiny amount, next to a favourite."]'::jsonb,'["Talk to a paediatrician if picky eating comes with weight loss, poor growth, frequent gagging or choking, or a very short list of accepted foods that keeps shrinking."]'::jsonb,array['src-aap-picky-eaters','src-aap-preschool-feeding']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-limited-variety','limited_variety','Building variety from what your child already eats','["Eating a variety of foods is a core message of the ICMR-NIN Dietary Guidelines for Indians (2024)."]'::jsonb,'["Change one thing at a time — the shape, the dip, the colour or the way it''s cut — rather than the whole food.","Rotate between a few accepted foods so no single food becomes the only option."]'::jsonb,'["Roughly how many different foods does your child eat in a typical week?"]'::jsonb,'["Note two foods your child eats every day and try a small variation of each this week."]'::jsonb,'["If the list of accepted foods is shrinking over time, discuss it with a paediatrician."]'::jsonb,array['src-icmr-dgi-2024','src-aap-picky-eaters']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-protein-foods','protein_foods','Everyday protein-containing foods','["Many everyday foods contain protein: dals and other pulses, curd and milk, paneer, eggs (if eaten), nuts and seeds, and combinations of cereals with pulses such as khichdi.","ICMR-NIN''s 2024 guidelines encourage getting good-quality protein through food combinations and discourage protein supplements for building body mass."]'::jsonb,'["Combine a cereal with a pulse in one dish (rice + dal, roti + chana).","Add a dairy food or ground nuts/seeds to a meal your child already accepts."]'::jsonb,'["Does your child eat dal, curd, paneer or eggs in any form?"]'::jsonb,'["Explore the quick ideas below, which each include a protein-containing food."]'::jsonb,'["If you are worried about your child''s growth, energy or health, a paediatrician or registered dietitian can assess this properly."]'::jsonb,array['src-icmr-dgi-2024']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-fruit-veg','fruit_veg','Making fruit and vegetables more familiar','["Repeated, low-pressure exposure helps children accept foods over time."]'::jsonb,'["Cook vegetables into foods your child already accepts (cheela, khichdi, parathas) — and also offer them visibly sometimes, so they become familiar.","Offer fruit in different cuts and colours, next to a favourite fruit."]'::jsonb,'["Are there any fruits or vegetables your child does eat, even occasionally?"]'::jsonb,'["Try one vegetable two different ways this week."]'::jsonb,'[]'::jsonb,array['src-aap-picky-eaters','src-aap-preschool-feeding']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-calcium','calcium','Calcium: what foods contain it','["A concern about calcium is not the same as a deficiency. This app cannot tell whether your child is getting enough calcium, and it does not diagnose deficiencies.","Milk, curd (yogurt) and cheese (including paneer) are main food sources of calcium; some vegetables such as broccoli and kale also contain it; some foods are fortified — check labels."]'::jsonb,'["Look at how often dairy foods or fortified alternatives already appear in your child''s day.","If dairy is avoided, ask a professional about suitable fortified alternatives."]'::jsonb,'["How much milk, curd or paneer does your child usually have in a day?","Is dairy avoided for any reason?"]'::jsonb,'["Review the food ideas that include a dairy food.","If a professional has assessed your child, follow their advice."]'::jsonb,'["If you suspect a deficiency, or a doctor has mentioned one, a paediatrician or registered dietitian should guide any changes — including whether a supplement is needed and how much.","Tell your child''s doctor about any supplements they take."]'::jsonb,array['src-ods-calcium']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-iron','iron','Iron: food sources and an important safety note','["A concern about iron is not a diagnosis. Iron deficiency can only be confirmed by a healthcare professional, usually with a blood test.","Plant foods such as lentils, beans, spinach, nuts and dried fruit, and iron-fortified foods, provide ''nonheme'' iron. Meat, poultry and fish also contain iron.","Eating a vitamin C food (citrus, tomatoes, peppers, broccoli, strawberries) in the same meal helps the body absorb plant iron.","Vegetarians may need more dietary iron because plant iron is absorbed less efficiently."]'::jsonb,'["Pair dals or greens with a vitamin C food such as lemon or tomato."]'::jsonb,'["How often does your child eat dal, beans, green leafy vegetables or eggs/meat?"]'::jsonb,'["Look at the legume-based ideas below.","Speak to a paediatrician if you suspect a deficiency."]'::jsonb,'["Do not give iron supplements without professional advice. Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6 — keep any supplements out of reach.","See a paediatrician if your child seems unusually tired, pale or unwell."]'::jsonb,array['src-ods-iron']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-vitamin-d','vitamin_d','Vitamin D: why food alone rarely tells the full story','["Very few foods naturally contain vitamin D; the body makes it when bare skin is exposed to sunlight, and some foods are fortified.","Too much vitamin D can be harmful — this almost always comes from supplements.","Whether a child needs a vitamin D supplement, and how much, is a question for a paediatrician."]'::jsonb,'[]'::jsonb,'["Has a doctor checked or mentioned vitamin D?"]'::jsonb,'["Discuss vitamin D with your child''s paediatrician rather than adjusting supplements yourself."]'::jsonb,'["Any vitamin D supplement amount should come from a healthcare professional."]'::jsonb,array['src-ods-vitamin-d']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-other-nutrient','other_nutrient','Concerns about a specific nutrient','["This app does not have reviewed education for every nutrient, and it cannot assess whether your child is getting enough of one."]'::jsonb,'["A varied diet across cereals, pulses, dairy, fruit and vegetables covers most needs for most children (ICMR-NIN)."]'::jsonb,'["Which nutrient are you concerned about, and why?"]'::jsonb,'["Note down what prompted the concern to share with a professional."]'::jsonb,'["If you are worried about your child''s growth, energy or health, a paediatrician or registered dietitian can assess this properly."]'::jsonb,array['src-icmr-dgi-2024']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-appetite','appetite','When your child refuses meals','["Young children''s appetites vary a lot from day to day. Pressure to eat can make children less likely to eat."]'::jsonb,'["Keep regular meal and snack times.","Offer small portions, and don''t make a separate meal when one is refused.","Stay calm and talk about the day rather than the food."]'::jsonb,'["Is the refusal new, or has it been going on for a while?","Has your child''s weight or energy changed?"]'::jsonb,'["Try a small, low-pressure snack from the ideas below between meals."]'::jsonb,'["See a paediatrician if meal refusal comes with weight loss, lethargy, vomiting, pain, or if it is persistent or worsening."]'::jsonb,array['src-aap-picky-eaters','src-aap-preschool-feeding']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-feeding-symptom','feeding_symptom','Constipation and other feeding-related symptoms','["Symptoms need a professional opinion — this app cannot assess them.","General guidance includes plenty of fluids (preferably water) and fibre-containing foods such as lentils, beans, oats, whole grains, apples, pears and broccoli."]'::jsonb,'["Include a fibre-containing food at meals and offer water regularly."]'::jsonb,'["How long has this been happening?"]'::jsonb,'["Contact your child''s doctor if any warning sign below applies."]'::jsonb,'["Talk to a doctor if constipation lasts more than two weeks — or sooner with fever, vomiting, unexplained weight loss, blood in the stool, bleeding from the rectum, or bloating."]'::jsonb,array['src-hmh-constipation']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-meal-prep','meal_prep','Making food preparation easier','["Simple, repeatable meals are fine. A few no-cook and one-pot options can cover busy days."]'::jsonb,'["Keep a few no-cook options (curd, fruit, roti rolls) for rushed mornings.","Cook once, use twice — a batch of khichdi or pancakes can cover another meal."]'::jsonb,'["How much time do you usually have for breakfast?"]'::jsonb,'["Filter the ideas below by prep time."]'::jsonb,'[]'::jsonb,array[]::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-product-question','product_question','Understanding your product''s instructions','["The pack (and the manufacturer''s official page) is the governing instruction for any product. This app shows the official instruction where it has been verified, and does not change quantities.","If the instruction for your exact variant has not been verified, check the pack — variants can differ."]'::jsonb,'[]'::jsonb,'["Which exact variant and flavour do you have (check the pack''s age band)?"]'::jsonb,'["Compare what you currently do with the official instruction shown below."]'::jsonb,'["Questions about how much of a supplement your child should take belong with a paediatrician or pharmacist."]'::jsonb,array[]::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-known-allergy','known_allergy','Food allergies: reading labels safely','["Read the label every time — even for products your child has eaten before. Ingredients and manufacturing can change.","''May contain'' warnings are voluntary, so a product without one can still carry a cross-contact risk.","If you are unsure whether a product is safe, contact the manufacturer.","This app filters ideas using the allergens you entered, but it cannot guarantee a product or recipe is safe: our ingredient data may be incomplete."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Check every pack label yourself before serving."]'::jsonb,'["An allergist or paediatrician should guide any severe allergy, and any decision to reintroduce a food."]'::jsonb,array['src-kidshealth-allergy-labels']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-supplement-questions','supplement_questions','Supplements: what this app will and won''t do','["This app can show a product''s official information. It will not tell you whether your child needs a supplement, how much to give, or whether to combine products.","A product containing a nutrient is not a treatment for an individual child''s deficiency.","Food first: the ICMR-NIN guidelines emphasise a varied diet."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Bring questions about supplement need or amount to a paediatrician or pharmacist."]'::jsonb,'["Always tell your child''s doctor about supplements your child takes."]'::jsonb,array['src-icmr-dgi-2024','src-ods-calcium']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-oral-care','oral_care','Oral-care products','["Toothpaste is not part of nutrition guidance in this app. Product information is shown as published by the manufacturer.","For the Little Joys 5+ toothpaste, the official page gives conflicting fluoride information. Check the pack and ask your child''s dentist which toothpaste and how much to use."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Ask your dentist about fluoride and toothpaste amount for your child''s age."]'::jsonb,'[]'::jsonb,array['src-lj-toothpaste-5']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-under-two','under_two','Feeding children under two','["Children under two have specific feeding needs. WHO guidance for 6–23 months emphasises a diverse diet and responsive feeding — responding to your child''s hunger and fullness cues.","WHO notes fortified products or supplements may help only where needs cannot be met with unfortified foods — a judgement for a healthcare professional.","This app does not yet have reviewed recipes or product guidance for under-twos, so it does not suggest any."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Discuss feeding questions with your paediatrician or a registered dietitian."]'::jsonb,'["Any supplement or product question for a child under two should go to a paediatrician."]'::jsonb,array['src-who-cf-2023']::text[],'approved');
insert into concern_education (id,concern_type,title,educational_content,food_guidance,missing_information_questions,recommended_next_steps,referral_conditions,evidence_source_ids,review_status) values ('edu-other','other','Your concern','["We may not have reviewed education for this specific concern yet. The general food ideas below may still help."]'::jsonb,'[]'::jsonb,'["Can you describe the concern in a sentence?"]'::jsonb,'[]'::jsonb,'["If you are worried about your child''s growth, energy or health, a paediatrician or registered dietitian can assess this properly."]'::jsonb,array[]::text[],'approved');
insert into concern_product_rules (id,concern_type,product_id,relationship_type,intended_purpose,eligibility_conditions,exclusion_conditions,parent_facing_explanation,evidence_source_id,review_status) values ('cpr-protein-nutrimix-2-6','protein_foods','lj-nutrimix-2-6-chocolate-350g','informational_food_format','Show manufacturer-stated information for parents who asked to learn about relevant products.','{"requires_assistance":["learn_products"],"min_age_months":24,"max_age_months":83}'::jsonb,'{"allergens":["tree_nut","milk"],"concern_statuses":[]}'::jsonb,'You asked to learn about relevant products. The manufacturer states this variant provides 5 g protein per pack-prepared serving. This is manufacturer information, not a recommendation that your child needs it — food sources of protein work too.','src-lj-nutrimix-2-6','approved');
insert into concern_product_rules (id,concern_type,product_id,relationship_type,intended_purpose,eligibility_conditions,exclusion_conditions,parent_facing_explanation,evidence_source_id,review_status) values ('cpr-calcium-gummies-4-6','calcium','lj-calcium-gummies-strawberry-4-6-30n','informational_contains_nutrient','Would show that this product contains calcium and vitamin D3 (manufacturer-stated).','{"requires_assistance":["learn_products"],"min_age_months":48,"max_age_months":83}'::jsonb,'{"allergens":[],"concern_statuses":["suspected","professional_identified"]}'::jsonb,'Contains calcium and vitamin D3 according to the manufacturer. A product containing calcium is not a treatment for a deficiency.','src-lj-calcium-4-6','pending_review');
insert into concern_product_rules (id,concern_type,product_id,relationship_type,intended_purpose,eligibility_conditions,exclusion_conditions,parent_facing_explanation,evidence_source_id,review_status) values ('cpr-picky-mvg-4-6','picky_eating','lj-multivitamin-gummies-4-6-30n','informational_contains_nutrient','Imported marketing association (''helps fulfil nutritional gaps due to picky eating''). Rejected: picky eating is handled with food ideas first.','{"requires_assistance":["learn_products"],"min_age_months":48,"max_age_months":83}'::jsonb,'{"allergens":[],"concern_statuses":[]}'::jsonb,'','src-lj-mvg-4-6','rejected');
insert into recommendation_rules (id,name,description,conditions,effects,output_type,required_review_status,review_status) values ('rule-under-two','Under-two safeguard','Children under 24 months: no product suggestions and no unreviewed recipes; show age-specific guidance.','[{"fact":"age_months","op":"lt","value":24}]'::jsonb,'{"block_product_suggestions":true,"block_unreviewed_recipes":true,"add_education_topics":["under_two"],"professional_guidance":"For children under two, please take feeding, supplement and product questions to your paediatrician.","warning":null}'::jsonb,'restriction','approved','approved');
insert into recommendation_rules (id,name,description,conditions,effects,output_type,required_review_status,review_status) values ('rule-suspected-deficiency','Suspected or identified deficiency','A nutrient concern marked suspected or professionally identified triggers referral guidance and blocks nutrient-product suggestions.','[{"fact":"concern_types","op":"includes_any","value":["calcium","iron","vitamin_d","other_nutrient"]},{"fact":"concern_status","op":"includes_any","value":["suspected","professional_identified"]}]'::jsonb,'{"block_product_suggestions":true,"block_unreviewed_recipes":false,"add_education_topics":["supplement_questions"],"professional_guidance":"You mentioned a suspected or professionally identified nutrient concern. Only a qualified professional can confirm a deficiency and decide on treatment, including any supplement and its amount. Please follow their advice; the food ideas here are general and do not replace it.","warning":null}'::jsonb,'referral','approved','approved');
insert into recommendation_rules (id,name,description,conditions,effects,output_type,required_review_status,review_status) values ('rule-severe-allergy','Severe allergy reported','Severe reactions: add an allergist referral and a label-checking warning.','[{"fact":"allergy_severity","op":"eq","value":"severe"}]'::jsonb,'{"block_product_suggestions":true,"block_unreviewed_recipes":false,"add_education_topics":["known_allergy"],"professional_guidance":"You reported a severe reaction. Please follow your allergist''s or paediatrician''s plan, and check every label yourself.","warning":"Severe allergy reported: product suggestions are switched off. Recipes are filtered, but always check each ingredient''s label."}'::jsonb,'warning','approved','approved');
insert into recommendation_rules (id,name,description,conditions,effects,output_type,required_review_status,review_status) values ('rule-any-allergy','Allergy education','Any reported allergy adds label-reading education.','[{"fact":"has_allergies","op":"eq","value":true}]'::jsonb,'{"block_product_suggestions":false,"block_unreviewed_recipes":false,"add_education_topics":["known_allergy"],"professional_guidance":null,"warning":null}'::jsonb,'education','approved','approved');
insert into recommendation_rules (id,name,description,conditions,effects,output_type,required_review_status,review_status) values ('rule-feeding-symptom','Feeding-related symptom','Symptom concerns always show referral criteria.','[{"fact":"concern_types","op":"includes","value":"feeding_symptom"}]'::jsonb,'{"block_product_suggestions":true,"block_unreviewed_recipes":false,"add_education_topics":["feeding_symptom"],"professional_guidance":"Symptoms such as constipation need a doctor''s view if they persist or come with warning signs (listed below).","warning":null}'::jsonb,'referral','approved','approved');
